import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, TurnUsage } from 'claude-code'

import type { Figures } from '../types'
import { cacheMiss, cacheTtl, money, row, SEPARATOR, thresholdsFrom, warnings } from './format'
import type { Thresholds } from './format'

const figures = atom({ plugin: 'usage-bar', key: 'figures' } as const, null)
const now = atom({ plugin: 'usage-bar', key: 'now' } as const, 0)
const warned = atom({ plugin: 'usage-bar', key: 'warned' } as const, [])
const turnStartCost = atom({ plugin: 'usage-bar', key: 'turnStartCost' } as const, null)
const cache = atom({ plugin: 'usage-bar', key: 'cache' } as const, null)

const TICK_MS = 60_000

async function measure($: EngineInterface): Promise<Figures> {
  const usage = await $.session.usage()
  const measured: Figures = {
    startedAt: usage.startedAt,
    limits: [...usage.rateLimits],
    costUsd: usage.cost?.usd ?? null,
    contextTokens: usage.context.tokens ?? null,
  }

  await update($, figures, () => measured)

  return measured
}

async function tick($: EngineInterface): Promise<void> {
  const time = await $.clock.now()
  await update($, now, () => time)
}

async function warn($: EngineInterface, measured: Figures, thresholds: Thresholds): Promise<void> {
  const given = new Set(await read($, warned))
  const fresh = warnings({ ...measured, thresholds, now: await $.clock.now() }).filter(w => !given.has(w.key))

  if (fresh.length === 0) {
    return
  }

  await update($, warned, keys => [...keys, ...fresh.map(w => w.key)].slice(-200))

  for (const warning of fresh) {
    $.ui.toast(`⚠ ${warning.text}`, { timeoutMs: 10_000 })
  }
}

async function currentCost($: EngineInterface): Promise<number | null> {
  return (await $.session.usage()).cost?.usd ?? null
}

/** Records a main-thread request as the cache's last refresh, warning when it re-wrote the cache. */
async function noteRequest($: EngineInterface, requestAt: number, usage: TurnUsage, thresholds: Thresholds) {
  const { startedAt, rateLimits } = await $.session.usage()
  const stored = await read($, cache)
  const miss = cacheMiss({
    previous: stored !== null && stored.sessionStartedAt === startedAt ? stored : null,
    requestAt,
    usage,
    ttl: cacheTtl(rateLimits),
    minTokens: thresholds.cacheMissWarnTokens,
  })

  await update($, cache, () => ({ sessionStartedAt: startedAt, requestAt, model: usage.model }))

  if (miss !== null) {
    $.ui.toast(`⚠ ${miss}`, { timeoutMs: 10_000 })
  }
}

export const register: Register = (on, options) => {
  const thresholds = thresholdsFrom(options)

  on('session.start', async ($, e, next) => {
    // The line the first version pinned under the prompt, if a reload left it.
    $.ui.status(undefined)
    // Countdowns move with the clock, not with the session's measurements.
    $.clock.every(TICK_MS, () => tick($))
    await measure($)
    await tick($)

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    const measured = await measure($)
    await tick($)
    await warn($, measured, thresholds)

    return next(e)
  })

  // Subagents keep caches of their own; the board follows the main thread's.
  on('turn.step', async function* ($, e, next) {
    if (e.agentId !== undefined) {
      return yield* next(e)
    }

    const requestAt = await $.clock.now()
    const result = yield* next(e)

    if (result.usage !== null) {
      try {
        await noteRequest($, requestAt, result.usage, thresholds)
      } catch {
        // The board is a bystander: a failed note must not touch the turn.
      }
    }

    return result
  })

  on('prompt.submit', async ($, e, next) => {
    const cost = await currentCost($)
    await update($, turnStartCost, () => cost)

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    const startedAt = await read($, turnStartCost)
    const cost = await currentCost($)

    if (startedAt !== null && cost !== null && cost - startedAt >= thresholds.turnCostWarnUsd) {
      $.ui.toast(`⚠ That turn cost ${money(cost - startedAt)} (session ${money(cost)}).`, { timeoutMs: 10_000 })
    }

    await update($, turnStartCost, () => null)

    return result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)
    const measured = await read($, figures)
    const mark = await read($, cache)
    const segments = row({
      limits: measured?.limits ?? [],
      costUsd: measured?.costUsd ?? null,
      contextTokens: measured?.contextTokens ?? null,
      // A mark left by the conversation before a /clear says nothing about this one.
      mark: mark !== null && mark.sessionStartedAt === measured?.startedAt ? mark : null,
      now: await read($, now),
      thresholds,
    })

    return (
      <Box paddingLeft={1}>
        <Text>
          {segments.flatMap((segment, index) => [
            ...(index === 0 ? [] : [<Text dimColor>{SEPARATOR}</Text>]),
            ...segment.parts.map(part => (
              <Text color={part.color} dimColor={part.dim}>
                {part.text}
              </Text>
            )),
          ])}
        </Text>
      </Box>
    )
  })
}

