import type { SessionRateLimit, TurnUsage } from 'claude-code'

import type { CacheMark } from '../types'

export type Thresholds = {
  costWarnUsd: number
  turnCostWarnUsd: number
  limitWarnPct: number
  cacheMissWarnTokens: number
}

export const DEFAULTS: Thresholds = {
  costWarnUsd: 5,
  turnCostWarnUsd: 2,
  limitWarnPct: 80,
  cacheMissWarnTokens: 30_000,
}

const FIVE_HOUR = 'five_hour'
const SEVEN_DAY = 'seven_day'

const MINUTE = 60_000
/** Claude Code's prompt-cache lifetime on a subscription. */
const CACHE_TTL_MS = 60 * MINUTE
/** Past a plan limit (usage overage) Claude Code drops to the API's default lifetime. */
const OVERAGE_CACHE_TTL_MS = 5 * MINUTE

export const SEPARATOR = ' | '

export type Level = 'success' | 'warning' | 'error'

/** A run of one style inside a segment. */
export type Part = { text: string; color?: Level; dim?: boolean }

/** One `|`-separated piece of the row. */
export type Segment = { key: string; parts: Part[] }

export const thresholdsFrom = (options: Readonly<Record<string, unknown>>): Thresholds => {
  const pick = (key: keyof Thresholds): number => {
    const value = options[key]

    return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : DEFAULTS[key]
  }

  return {
    costWarnUsd: pick('costWarnUsd'),
    turnCostWarnUsd: pick('turnCostWarnUsd'),
    limitWarnPct: pick('limitWarnPct'),
    cacheMissWarnTokens: pick('cacheMissWarnTokens'),
  }
}

const find = (limits: readonly SessionRateLimit[], kind: string): SessionRateLimit | undefined =>
  limits.find(limit => limit.kind === kind)

/** `42m`, `2h 14m`, `1d 8h`; `now` once the time has passed. */
export const duration = (ms: number): string => {
  const minutes = Math.ceil(ms / MINUTE)

  if (minutes <= 0) {
    return 'now'
  }

  const days = Math.floor(minutes / 1440)
  const hours = Math.floor((minutes % 1440) / 60)
  const mins = minutes % 60

  if (days > 0) {
    return `${days}d ${hours}h`
  }

  if (hours > 0) {
    return `${hours}h ${mins}m`
  }

  return `${mins}m`
}

export const countdown = (resetsAt: string | undefined, now: number): string | null => {
  if (resetsAt === undefined) {
    return null
  }

  const at = Date.parse(resetsAt)

  return Number.isNaN(at) ? null : duration(at - now)
}

/** Green below half, yellow from half, red from 80%: the person's own status line scheme. */
export const levelOf = (percentUsed: number): Level =>
  percentUsed >= 80 ? 'error' : percentUsed >= 50 ? 'warning' : 'success'

const percent = (value: number): string => `${Math.round(value)}%`

export const money = (usd: number): string => `$${usd.toFixed(2)}`

/** `950`, `48k`, `1.2M`. */
export const tokens = (count: number): string =>
  count >= 1_000_000
    ? `${(count / 1_000_000).toFixed(1)}M`
    : count >= 1000
      ? `${Math.round(count / 1000)}k`
      : `${count}`

const limitSegment = (key: string, title: string, limit: SessionRateLimit | undefined, now: number): Segment => {
  if (limit === undefined) {
    return { key, parts: [{ text: `${title}: waiting for first reply`, dim: true }] }
  }

  const level = levelOf(limit.percentUsed)
  const resets = countdown(limit.resetsAt, now)
  const tail = resets === null ? '' : resets === 'now' ? ', resets now' : `, resets in ${resets}`

  return {
    key,
    parts: [{ text: `${title} ` }, { text: `${percent(limit.percentUsed)} used`, color: level }, { text: tail, dim: true }],
  }
}

export const sessionText = (costUsd: number, thresholds: Thresholds): { text: string; isExpensive: boolean } => {
  const isExpensive = costUsd >= thresholds.costWarnUsd

  return { text: `${isExpensive ? '⚠ ' : ''}This session ${money(costUsd)}`, isExpensive }
}

/**
 * How long a prompt-cache entry lives: an hour on a subscription, five minutes
 * once a plan limit is spent (overage); unknown without a plan reading.
 */
export const cacheTtl = (limits: readonly SessionRateLimit[]): number | null => {
  const plan = [find(limits, FIVE_HOUR), find(limits, SEVEN_DAY)].filter(limit => limit !== undefined)

  if (plan.length === 0) {
    return null
  }

  return plan.some(limit => limit.percentUsed >= 100) ? OVERAGE_CACHE_TTL_MS : CACHE_TTL_MS
}

export type CacheInput = {
  mark: CacheMark | null
  limits: readonly SessionRateLimit[]
  /** Tokens the next request re-sends: the live context window's fill. */
  contextTokens: number | null
  now: number
}

/** The entry lives from the start of the last request that read or wrote it. */
const cacheSegment = ({ mark, limits, contextTokens, now }: CacheInput): Segment | null => {
  if (mark === null) {
    return { key: 'cache', parts: [{ text: 'Cache: waiting for first reply', dim: true }] }
  }

  const ttl = cacheTtl(limits)

  if (ttl === null) {
    return null
  }

  const left = duration(mark.requestAt + ttl - now)

  if (left !== 'now') {
    return { key: 'cache', parts: [{ text: 'Cache ' }, { text: `expires in ${left}`, dim: true }] }
  }

  const rewrite = contextTokens === null ? '' : `: next reply re-caches ~${tokens(contextTokens)} tokens`

  return { key: 'cache', parts: [{ text: 'Cache ' }, { text: `expired${rewrite}`, color: 'warning' }] }
}

export type RowInput = CacheInput & {
  costUsd: number | null
  thresholds: Thresholds
}

export const row = (input: RowInput): Segment[] => {
  const { limits, now, costUsd, thresholds } = input
  const segments = [
    limitSegment('five-hour', '5h limit', find(limits, FIVE_HOUR), now),
    limitSegment('seven-day', 'Weekly limit', find(limits, SEVEN_DAY), now),
  ]

  if (costUsd !== null) {
    const session = sessionText(costUsd, thresholds)
    segments.push({
      key: 'session',
      parts: [session.isExpensive ? { text: session.text, color: 'warning' } : { text: session.text }],
    })
  }

  const cache = cacheSegment(input)

  if (cache !== null) {
    segments.push(cache)
  }

  return segments
}

export const plainText = (segments: readonly Segment[]): string =>
  segments.map(segment => segment.parts.map(part => part.text).join('')).join(SEPARATOR)

export type MissInput = {
  /** The main thread's previous answered request this session; null for its first. */
  previous: CacheMark | null
  requestAt: number
  usage: TurnUsage
  ttl: number | null
  minTokens: number
}

/**
 * The warning for a request that re-wrote the cache instead of reading it, or
 * null. The first request of a session writes by design and never warns. The
 * cause is read from what the mod can see: a gap past the lifetime, another
 * model; anything else changed the start of the prompt.
 */
export const cacheMiss = ({ previous, requestAt, usage, ttl, minTokens }: MissInput): string | null => {
  const written = usage.cache_creation_input_tokens

  if (previous === null || written < minTokens || usage.cache_read_input_tokens >= written) {
    return null
  }

  const gap = requestAt - previous.requestAt
  const cause =
    ttl !== null && gap >= ttl
      ? ` after ${duration(gap)} idle`
      : previous.model !== usage.model
        ? ' after the model changed'
        : '; the start of the prompt changed (/compact, CLAUDE.md, MCP tools or effort)'

  return `Cache miss: re-cached ${tokens(written)} tokens${cause}.`
}

export type Warning = { key: string; text: string }

export type WarningInput = {
  limits: readonly SessionRateLimit[]
  costUsd: number | null
  thresholds: Thresholds
  now: number
}

const LABELS: Record<string, string> = { [FIVE_HOUR]: 'Session (5h)', [SEVEN_DAY]: 'Weekly' }

/**
 * Every warning the figures call for now, each under a key that says when it
 * was already given: a limit's warnings re-arm with its next window, the cost
 * ones last the session.
 */
export const warnings = ({ limits, costUsd, thresholds, now }: WarningInput): Warning[] => {
  const found: Warning[] = []

  if (costUsd !== null && costUsd >= thresholds.costWarnUsd) {
    // $5, $10, $20, ...: the highest step passed, so a jump warns once.
    let step = thresholds.costWarnUsd

    while (step * 2 <= costUsd) {
      step *= 2
    }

    found.push({
      key: `cost:${step}`,
      text: `This session has cost ${money(costUsd)} so far (past ${money(step)}). Consider /compact or a fresh session.`,
    })
  }

  const levels = [...new Set([95, thresholds.limitWarnPct])].sort((a, b) => b - a)

  for (const limit of limits) {
    const label = LABELS[limit.kind]

    if (label === undefined) {
      continue
    }

    for (const level of levels) {
      if (limit.percentUsed >= level) {
        const resets = countdown(limit.resetsAt, now)

        found.push({
          key: `limit:${limit.kind}:${level}:${limit.resetsAt ?? ''}`,
          text: `${label} limit at ${percent(limit.percentUsed)} used${resets ? `, resets in ${resets}` : ''}.`,
        })

        break
      }
    }
  }

  return found
}

