      "type": "number",
      "title": "Limit warning (%)",
      "description": "Toast when the 5-hour or weekly limit reaches this percentage (and again at 95%).",
      "default": 80
    },
    "cacheMissWarnTokens": {
      "type": "number",
      "title": "Cache miss warning (tokens)",
      "description": "Toast when one request re-writes at least this many tokens to the prompt cache instead of reading them.",
      "default": 30000
    }
  }
}

