/** One rate-limit window as `$.session.usage()` reports it. */
export type Limit = { kind: string; percentUsed: number; resetsAt?: string }

/** What the board draws from: the session's last measurement. */
export type Figures = {
  /** `$.session.usage().startedAt`: which session the figures belong to. */
  startedAt: number
  limits: Limit[]
  costUsd: number | null
  /** Tokens the next request re-sends: the live context window's fill. */
  contextTokens: number | null
}

/** The main thread's last answered model request, which last refreshed the prompt cache. */
export type CacheMark = {
  /** `$.session.usage().startedAt` of the session the request belongs to. */
  sessionStartedAt: number
  /** When the request began, in `$.clock.now()`'s milliseconds. */
  requestAt: number
  /** The model that answered it; the cache is per model. */
  model: string
}

declare module 'claude-code' {
  interface PluginState {
    'usage-bar': {
      figures: Figures | null
      now: number
      warned: string[]
      turnStartCost: number | null
      cache: CacheMark | null
    }
  }
}
